window.MAMI_AGE_NOTES={"0-6m": {"tips": ["Start with the basics: swaddles, a gentle wash and a few muslins. Big toys can wait.", "A carrier gives you two free hands in the first months."], "safe": ["Put baby to sleep on their back on a flat, empty surface. No pillows, bumpers or loose blankets.", "Stop swaddling as soon as baby shows signs of rolling."]}, "6-12m": {"tips": ["Solids usually start around 6 months; fruit feeders and soft spoons make it easier.", "A big soft mat gives a safe space to sit, crawl and play."], "safe": ["Stay with baby while they eat and cut food into safe shapes.", "Cover sockets and block stairs before baby crawls."]}, "1-2y": {"tips": ["First steps: push and balance toys build confidence.", "Simple picture books are perfect at this age."], "safe": ["Under 3s still put everything in their mouth, so watch for small parts.", "Fix tall furniture to the wall."]}, "2-3y": {"tips": ["Pretend play, drawing and busy books keep little hands happy.", "A kids' table and stool help them do things by themselves."], "safe": ["Small parts are still a choking risk until 3.", "Lock away cleaning products and medicines."]}, "3-5y": {"tips": ["Books, drawing and activity books build pre-school skills.", "Active play such as balance boards burns energy indoors."], "safe": ["Use a helmet on anything with wheels.", "Practise road safety on every walk."]}};
